from stockflow.normalize_sku import normalize_sku
from stockflow.on_hand_by_location import on_hand_by_location
from stockflow.parse_location import parse_location

def _canonical_loc(loc: str) -> str:
    z, a, s, l = parse_location(loc)
    return f"{z}-{a:02d}-{s:02d}-{l}"

def cycle_count_variance(lines: Iterable[str], case_sizes: Mapping[str, int], counts: Mapping[Tuple[str, str], int]) -> List[Tuple[str, str, int]]:
    system_stock = on_hand_by_location(lines, case_sizes)
    norm_counts: Dict[Tuple[str, str], int] = {}
    counted_locs: Set[str] = set()

    for (sku, loc), qty in counts.items():
        if qty < 0:
            raise ValueError(f"negative count: {qty}")
        n_sku, n_loc = normalize_sku(sku), _canonical_loc(loc)
        norm_counts[(n_sku, n_loc)] = norm_counts.get((n_sku, n_loc), 0) + qty
        counted_locs.add(n_loc)

    variances = []
    all_pos = set(system_stock.keys()) | set(norm_counts.keys())
    for sku, loc in all_pos:
        if loc not in counted_locs: continue
        v = norm_counts.get((sku, loc), 0) - system_stock.get((sku, loc), 0)
        if v != 0:
            variances.append((sku, loc, v))

    return sorted(variances, key=lambda x: (x[1], x[0]))"
    }
  }
}
